use std::collections::BTreeSet; #[derive(Debug)] pub struct Scene{pub nodes:Vec<String>,pub signals:Vec<(String,String)>} pub fn parse(s:&str)->Result<Scene,String>{let mut n=Vec::new();let mut g=Vec::new();for l in s.lines(){let l=l.trim();if let Some(v)=l.strip_prefix("@node "){n.push(v.split_whitespace().next().ok_or("bad node")?.into())}else if let Some(v)=l.strip_prefix("@signal "){let(a,b)=v.split_once("->").ok_or("bad signal")?;g.push((a.trim().into(),b.trim().into()))}}let p:BTreeSet<_>=n.iter().map(String::as_str).collect();for(a,b)in&g{if !p.contains(a.rsplit_once('.').ok_or("bad source")?.0)||!p.contains(b.rsplit_once('.').ok_or("bad target")?.0){return Err("unresolved static signal".into())}}Ok(Scene{nodes:n,signals:g})}
